"""Build the readable HTML report from executed result tables, without network access."""
from pathlib import Path
import json, html
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
def load(n):return json.loads((ROOT/'results'/n).read_text())
def table(df):return df.to_html(index=False,border=0,float_format=lambda x:f'{x:,.3g}')
def main():
 h=load('hypotheses.json');v=load('validation.json');d=load('descriptive.json')
 figures=[('01_timeline','All 2,300 domestic-bird records are shown in the upper panel, with WOAH non-poultry separated. The lower panel sums birds only in the 1,426 poultry records. Counts and birds are different outcomes. November 2026 is incomplete.'),('02_month_year_heatmap','Poultry detections only. Counts are displayed for the 56 analysis months, March 2022–October 2026. Missing edge months are blank, rather than zero. Counts are unadjusted for month length.'),('03_seasonal_tests','Left: year-adjusted Poisson contrasts with log(days) offset and HAC(3) 95% confidence intervals. Winter is an exploratory contrast. Right: within-type seasonal shares over the same complete months; market/sales and WOAH non-poultry excluded.'),('04_geography','Cumulative poultry counts, February 2022–4 November 2026, on Census 2024 state boundaries. Insets are resized for visibility. Zero means no reported poultry record in this snapshot; there are no farm-population denominators. Color scales differ between panels.'),('05_wild_poultry_lags','Complete-month national counts. Wild-bird analysis excludes captive wild birds and feral domestic birds. Log1p permits months with zero detections. Adjusted correlations use residuals after calendar-month and year effects. Neither curve establishes transmission direction.'),('06_burden_concentration','Poultry records only, full descriptive window. Left: seven production categories with largest affected-bird totals; shares use only those seven categories as denominators. Right: cumulative birds versus cumulative events after sorting by flock size.'),('07_surveillance','Top: wild-bird confirmation counts for the three largest surveillance-method categories; agency harvest is omitted. Bottom: collection-to-confirmation delays by confirmation year, excluding unknown, invalid and negative intervals. Late reporting and changing surveillance can distort apparent timing.'),('08_state_shares','Top 12 states by recorded poultry events in the inference window. Each cell is a share of all poultry events in that calendar year; omitted states account for the remainder. Edge years cover different months. The 2023–2025 sensitivity excludes both edge years.')]
 annual=pd.DataFrame({'Year':list(d['annual_poultry_events']),'Poultry detection records':list(d['annual_poultry_events'].values()),'All domestic-bird records':list(d['annual_all_events'].values()),'Affected poultry birds':list(d['annual_poultry_birds'].values())})
 annual['Coverage']=['Feb–Dec','Jan–Dec','Jan–Dec','Jan–Dec','Jan–4 Nov']
 ratios=pd.DataFrame(h['H1']).rename(columns={'season':'Season vs summer','ratio':'Count ratio','ci_low':'95% CI lower','ci_high':'95% CI upper','p_two_sided':'Two-sided p'})
 ratios['Holm-adjusted p']=[h['holm_p']['H1_spring'],h['holm_p']['H1_autumn'],float('nan')]
 content=f'''
<h1>What can reported outbreaks tell us about bird flu in U.S. poultry?</h1>
<p class="subtitle">An executed observational investigation • USDA APHIS snapshots retrieved 6 November 2026 • Analysis window: March 2022–October 2026</p>
<div class="takeaway"><b>Main finding:</b> Reported poultry outbreaks have a pronounced summer lull, but their timing and geographic concentration change from year to year. Winter activity is substantial. Large egg-layer flocks dominate affected-bird totals. A simple national wild-bird count is not established here as a reliable advance warning.</div>
<h2>Abstract</h2>
<p>We downloaded official APHIS poultry and wild-bird detection records and investigated seasonal patterns, production-group differences, geographic composition and wild-bird temporal associations. The domestic-bird export contains 2,300 detection records from 8 February 2022 to 4 November 2026; 1,426 meet our poultry definition, representing 211.62 million reported affected birds. The separate wildlife file contains 20,539 rows through 27 October 2026. In 56 complete months, year-adjusted spring and autumn poultry detection counts per day were 6.74 (95% CI 3.58–12.70) and 7.46 (4.09–13.59) times summer counts. The exploratory winter contrast was 11.49 (5.61–23.50). Production-group seasonal differences were small in the pooled window but changed materially when restricting to full calendar years. Geographic composition varied strongly across years. A one-month wild-bird lead was not supported after calendar-month and year adjustment. These are patterns of confirmed detection and reported flock size, not estimates of infection incidence or causal effects.</p>
<h2>Background</h2>
<p>APHIS confirms HPAI detections in commercial, backyard and other domestic birds. The ongoing U.S. commercial-poultry event began in February 2022. Its public dashboard mixes production categories, so defining the outcome is essential. APHIS describes a relationship between seasonal wild-bird movement and poultry detections. We examine how consistently that description fits the downloaded records rather than assuming a fixed seasonal curve. <a href="#r1">[1]</a></p>
<p>Independent sequence-based work identifies repeated wildlife introductions into domestic birds, providing biological context for examining joint timing. Aggregate surveillance counts cannot reproduce phylogenetic transmission reconstruction. <a href="#r3">[3]</a></p>
<h2>Hypotheses specified before analysis</h2>
<ol><li><b>H1:</b> Spring (March–May) and autumn (September–November) have higher reported poultry detection counts per day than summer (June–August).</li><li><b>H2:</b> Commercial and backyard-poultry records have different seasonal distributions.</li><li><b>H3:</b> The state composition of recorded poultry events changes across years.</li><li><b>H4, exploratory:</b> Higher wild-bird detections are associated with more poultry detections in the following month after calendar adjustment.</li></ol>
<p>The dated <a href="analysis-plan.txt">analysis plan</a> was saved before computing outbreak summaries, after inspecting the existing workspace CSV schema and first rows and reading background sources. This was not a registered preregistration. Negative-binomial sensitivity, detailed production/year inspection and the surveillance-delay investigation were added after inspecting initial results.</p>
<h2>Data acquisition, coverage and units</h2>
<p>The official APHIS Tableau dashboard’s default CSV returned a four-month backyard summary, which was rejected as a historical event source. Its “X - Table by Confirmation Date” crosstab was successfully downloaded through the public browser interface, yielding all 2,300 rows. The third-party mirror already present in the repository was not used in the final analysis. Wild-bird data were downloaded directly from the CSV wired to APHIS’s official wildlife page. State boundaries came from the U.S. Census Bureau’s 2024 1:20 million cartographic shapefile. Raw bytes, SHA256 hashes, retrieval dates and source URLs are retained in <a href="sources/download_manifest.json">the download manifest</a> and <a href="sources/poultry_manifest.json">poultry export manifest</a>. <a href="#r1">[1]</a> <a href="#r2">[2]</a> <a href="#r7">[7]</a></p>
<ul><li><b>Detection event:</b> one row in the poultry confirmation export. A row is treated as a confirmed flock/premises event, not one infected bird. Event labels are unique in this export, but do not establish unique physical premises across time.</li><li><b>Affected flock:</b> the flock represented by that event. Repeated infections at a physical site cannot reliably be identified from event-specific “Special ID” labels.</li><li><b>Affected birds:</b> the reported flock-size burden associated with the event; this includes birds affected by control measures and must not be interpreted as laboratory-confirmed individual infections or deaths.</li><li><b>Wild-bird row:</b> a positive detection record, with species and sampling information. No unique specimen identifier or negative-test denominator is provided in the CSV. It cannot estimate population prevalence.</li></ul>
<p>The export comprises 1,060 commercial-production records, 286 records labelled simply “WOAH Poultry,” 80 market/sales records, and 874 “WOAH Non-Poultry” records. APHIS’s epidemiologic reporting distinguishes backyard WOAH poultry from backyard non-poultry, supporting use of the unqualified WOAH Poultry category as a <b>backyard-poultry proxy</b>; the export does not provide an independent backyard flag. Markets are retained in the overall poultry outcome but excluded from the commercial-versus-backyard comparison. WOAH non-poultry is excluded from the primary poultry outcome and included in a broader sensitivity analysis. This definition is narrower than the domestic-bird dashboard headline. The full domestic-bird file covers 50 states plus Puerto Rico; the poultry subset has records in 47 states. <a href="#r6">[6, p. 6]</a></p>
{table(annual)}
<p>These are present-day retrospective records, subject to later revisions. No January 2022 poultry baseline is inferred. November 2026 is incomplete, and 2026 annual totals should not be directly compared with complete years as trends in risk.</p>
<h2>Cleaning and methodology</h2>
<p>The UTF-16 Tableau export is a wide crosstab: dates in columns describe control-area release, while the row’s confirmation date is the epidemiologic time variable. We fill repeated row headings, validate exactly one populated affected-bird cell per row, parse the value and preserve its release heading. All 2,300 rows pass date, state-name and nonnegative integer bird-count checks. Ten records share a date/state/county/type/bird-count signature but have different event labels; none was deleted. Among wild-bird rows, 7,447 have repeated complete public-field signatures; these may represent different birds and are retained. There are 277 “Unknown” collection dates and one malformed value (“2/19/215”), plus 10 negative collection-to-confirmation intervals. Collection-date sensitivity excludes those invalid intervals; confirmation-date analyses retain them. <a href="results/validation.json">Full validation output</a>.</p>
<p>Zero-row months are filled with zero reported detections, which does not prove zero infections. Primary inference excludes February 2022, the first observed poultry month, and November 2026, the retrieval month. The remaining 56 months contain 1,417 poultry events. Seasons are meteorological; December is grouped with January–February under its calendar year for year adjustment, not as a migration-year cohort.</p>
<p>H1 uses monthly Poisson regression with year and season indicators and log(calendar days) offset. Heteroskedasticity/autocorrelation-consistent covariance uses three monthly lags. Confidence intervals are marginal Wald 95% intervals, not simultaneous intervals. We report a negative-binomial sensitivity because the Pearson dispersion is {h['H1_dispersion']:.2f}. H2 uses a seasonal-by-type Pearson statistic with 4,999 type-label permutations within year. H3 permutes year labels among events for the state-by-year statistic; permutation avoids sparse-cell chi-square approximations. Both report Cramér’s V. H3’s permutation assumes exchangeable events and does not preserve outbreak clusters; its p-value can be too optimistic under common-source or local transmission. Effect sizes and full-year stability carry more weight.</p>
<p>Holm adjustment covers four primary tests: spring versus summer, autumn versus summer, H2 and H3. Tests are two-sided. H1 winter, all sensitivities and H4 are exploratory and not included in that family. H4 regresses log(1 + poultry events) on the previous month’s log(1 + wild-bird records), calendar-month and year effects, with HAC(3) covariance. It includes wild birds only, excluding captive wild birds and feral domestic birds. We examine first differences and collection dates as sensitivities and show lags −3 through +3 descriptively. Lag searches do not select a winning significance test. A fixed random seed (8050) makes permutation output reproducible.</p>
<h2>Results</h2>
<h3>H1: A persistent summer lull, with substantial winter activity</h3>
{table(ratios)}
<p>Both planned spring and autumn contrasts support H1 in the recorded data after multiplicity adjustment. Full-year 2023–2025 sensitivities give ratios of 4.31 and 10.89. Negative-binomial estimates are 5.93 and 8.25, also above one; adding WOAH non-poultry yields 5.57 and 6.54. These methods therefore agree on the broad summer contrast. Large overdispersion, limited annual replication and season-by-year variation make precise effect sizes less certain than nominal p-values suggest. Calendar season also captures husbandry, production cycles, testing effort and weather.</p>
<p><b>Unexpected result:</b> winter has the highest point estimate, although winter versus autumn was not tested. In 2025, the primary poultry outcome has 213 winter events, 132 autumn events, 52 spring events and four summer events. Thus a simple “spring and autumn only” story misses important winter burden. This does not refute migration-related introductions; late-autumn exposure, persistent circulation, farm clusters, detection delay and production composition are possible explanations, not mechanisms established by these data. The revised descriptive hypothesis is a broad cool-season elevation with year-specific peaks.</p>
<h3>H2: No stable pooled production-group difference</h3>
<p>In the main window, χ² = {h['H2']['chi2']:.2f}, V = {h['H2']['cramers_v']:.3f}, within-year permutation p = {h['H2']['permutation_p']:.4f} (Holm p = {h['holm_p']['H2']:.4f}; n = 1,337). Commercial records place 37.6% of events in winter versus 30.4% in the backyard-poultry proxy. The primary evidence does not support a consistent pooled difference, but this is not evidence of equivalence.</p>
<p><b>Important sensitivity:</b> Restricting to 2023–2025 yields V = {h['H2_full_years']['cramers_v']:.3f} and permutation p = {h['H2_full_years']['permutation_p']:.4f} (n = 756). In 2023, 21 of 55 backyard-proxy records occurred in spring, compared with seven of 146 commercial records. In 2022, corresponding spring shares were 37/88 and 175/297 within the primary window, reversing that contrast. Grouping all backyard poultry and non-poultry gives main-window p = {h['H2_including_nonpoultry']['permutation_p']:.4f}. Results depend on time window and category definition; a universal group difference is not justified. Geography and production types are plausible confounders. For example, 36 of the 76 backyard-proxy records in 2025 were in Indiana; nationally pooled patterns can reflect a few local clusters. See <a href="results/h2_by_year.csv">year-specific counts</a>.</p>
<h3>H3: Geographic composition changes</h3>
<p>The state-by-year association is large: χ² = {h['H3']['chi2']:.2f}, V = {h['H3']['cramers_v']:.3f}, permutation p = {h['H3']['permutation_p']:.4f}, Holm p = {h['holm_p']['H3']:.4f}. The full-year 2023–2025 analysis remains different (V = {h['H3_full_years']['cramers_v']:.3f}, p = {h['H3_full_years']['permutation_p']:.4f}). Of 235 state-year cells, {h['H3']['cells_expected_under_5']} have expected counts below five, making the permutation approach preferable to the asymptotic approximation, subject to its event-exchangeability caveat. The Monte Carlo p-value floor is 0.0002, not zero.</p>
<p>Across the complete descriptive window, Minnesota has the most poultry-event records (187), followed by Indiana (184) and South Dakota (159). Iowa leads affected-bird totals (30.79 million), followed by California (25.50 million) and Ohio (25.36 million). These contrasting rankings show why “most outbreaks” and “most birds affected” answer different questions. State farm inventories, species mix, surveillance coverage and clustered transmission could all change the composition. Counts do not identify the highest per-farm or per-bird risk.</p>
<h3>H4: Shared national timing does not establish a warning signal</h3>
<p>Wild-bird and poultry log counts correlate in the same month (r = 0.549), and with wild birds one month earlier (r = 0.486). After calendar-month and year adjustment, same-month residual correlation is 0.024. The adjusted one-month lead coefficient is {h['H4_exploratory']['beta']:.3f} (95% CI {h['H4_exploratory']['ci_low']:.3f} to {h['H4_exploratory']['ci_high']:.3f}, p = {h['H4_exploratory']['p']:.3f}, 55 months). First differences give β = {h['H4_exploratory']['first_difference']['beta']:.3f}, p = {h['H4_exploratory']['first_difference']['p']:.3f}. The positive adjusted association hypothesized in H4 is not supported here; the uncertainty interval includes both signs.</p>
<p>Collection-date sensitivity gives β = {h['H4_exploratory']['collection_date_sensitivity']['beta']:.3f} (95% CI {h['H4_exploratory']['collection_date_sensitivity']['ci_low']:.3f} to {h['H4_exploratory']['collection_date_sensitivity']['ci_high']:.3f}, p = {h['H4_exploratory']['collection_date_sensitivity']['p']:.3f}). This is not a validated forecast: it uses retrospective collections that may not have been reported at the time. National aggregation can hide local links, calendar adjustment may absorb biologically relevant seasonal effects, and 55 months offer limited independent information. We cannot conclude that wildlife has no role in poultry infection.</p>
<p><b>Surveillance investigation:</b> Collection-to-confirmation delay has a median of 15 days, 90th percentile of 151 days and 95th percentile of 257 days; 5,230 rows exceed 30 days. These summaries include all wildlife classifications with parseable dates, including the ten negative intervals in the raw quantiles. Figure 7 excludes negative intervals. Such delays can shift wildlife detections across seasons, while hunter harvest and mortality surveillance select different populations. APHIS explicitly describes backlog processing and confirmation-date reporting. <a href="#r2">[2]</a> Neither temporal order in the CSV nor correlation is enough to infer transmission direction.</p>
<h3>Bird burden is dominated by very large flocks</h3>
<p>The ten largest poultry events account for {d['top10_events_bird_share']:.1%} of all reported affected poultry birds; the largest 1% of events (15 records) account for {d['top1pct_events_bird_share']:.1%}. Table-egg layer operations contribute 154.73 million birds across 139 records, whereas turkey meat-bird operations contribute 22.48 million across 521 records. Median reported affected birds are 36,200 for commercial events, 1,000 for the backyard-poultry proxy and 40 for WOAH non-poultry. Changing production mix can therefore generate a large increase in bird totals without a corresponding increase in event count.</p>
<h2>Discussion and comparison with research</h2>
<p>Damodaran, Jaeger and Moncla’s peer-reviewed phylogenetic study reconstructed repeated wildlife-to-domestic introductions in the early North American epizootic and estimated earlier infection in backyard birds. Our later national count analysis supports broad temporal structure, but does not measure infection time or reproduce their host-transition estimates. Our lack of a robust one-month national lead is therefore an unresolved scale-and-measurement difference, not a direct contradiction of their sequence-based result. <a href="#r3">[3]</a></p>
<p>Ssematimba and colleagues inferred within-flock introduction times using mortality and diagnostic information; their combined median time to a first positive sample was six days. That distinction between infection and detection matters here: a confirmation date cannot be interpreted as the moment virus entered a flock. We do not have the inputs needed to reconstruct introduction dates. <a href="#r4">[4]</a></p>
<p>Harrington and colleagues documented the spread of genotype D1.1 through coordinated North American surveillance during autumn 2024. Their findings provide a plausible reason to expect changing temporal and geographic patterns as viral lineages change. Our public event table lacks genotypes, so attributing any particular peak to D1.1 would exceed the evidence. <a href="#r5">[5]</a></p>
<p>APHIS’s September 2025 epidemiologic report documents both independent introductions and common-source/lateral transmission, including a changing contribution from dairy-associated pathways. Those investigations explain why a wildlife-seasonality story need not explain every poultry cluster. Our event-only analysis cannot assign transmission routes. <a href="#r6">[6]</a></p>
<h2>Limitations and research integrity</h2>
<ul><li><b>Ascertainment:</b> Confirmed events undercount all infections; commercial reporting incentives, flock monitoring, wildlife species selection and reactive sampling vary.</li><li><b>Denominators:</b> No monthly, production-specific population of susceptible flocks was acquired. We estimate recorded counts per unit of calendar time, not per-flock infection rates. Bird inventories and annual birds processed are incompatible substitutes for flock-time denominators.</li><li><b>Dependence:</b> Events can cluster in time and space or share transmission sources. HAC(3) does not solve every dependence structure; only five calendar years are represented, and permutation p-values assume more independence than field outbreaks may provide.</li><li><b>Classification:</b> WOAH poultry/non-poultry definitions and production labels affect case inclusion. Backyard assignment is inferred from the source reporting convention rather than an independent export flag. The “Special ID” label is not a proven stable physical-premises identifier.</li><li><b>Snapshot and delays:</b> Recent months are provisional, backlogs can alter historic curves, and collection-date analysis remains right-truncated. A nonempty month is not necessarily fully reported. The latest dates differ between the poultry and wildlife sources.</li><li><b>Model specification:</b> Year/season effects are parsimonious summaries of changing biology and surveillance. Full-year H2 results disagree with the pooled conclusion; reporting only the more significant window would be misleading. Seasonal ratios should not be treated as universal biological constants.</li><li><b>Causality:</b> Weather, migratory activity, farm density, production mix, biosecurity, dairy proximity and surveillance effort were not jointly measured. Correlation cannot distinguish them, and ecological associations do not identify a farm-level mechanism.</li></ul>
<h2>Three follow-up questions</h2>
<ol><li><b>Can timely wildlife surveillance improve local warning?</b> Assemble county-week sample collection, test-negative and publication-date data, stratify by species/method and evaluate prospective predictions on held-out seasons. Compare against a season-only baseline and measure lead time and false alarms.</li><li><b>How much of the geographic shift reflects poultry production?</b> Link type-specific event counts with compatible farm inventories and time-varying susceptible-flock denominators. NASS’s public Census/Quick Stats offers useful starting data, but suppressed county cells, farm definitions and changing inventories require careful alignment. <a href="#r8">[8]</a></li><li><b>What drives winter peaks and group differences?</b> Combine stable premises identifiers, production type, genomic introduction assignments, dairy proximity and NOAA temperature/precipitation with outbreak timing. Compare within-region, within-type patterns to separate shared weather exposure from clustered transmission. NOAA offers public quality-controlled weather series; they were investigated as potential inputs, not analyzed here. <a href="#r9">[9]</a></li></ol>
<h2>Figures</h2>
'''
 for name,caption in figures:
  content+=f'<figure><a href="figures/{name}.svg"><img src="figures/{name}.png" alt="{html.escape(caption)}"></a><figcaption>{html.escape(caption)} Click for vector SVG.</figcaption></figure>'
 refs=[('r1','USDA APHIS. Confirmations of Highly Pathogenic Avian Influenza in Commercial and Backyard Flocks. Live dashboard and detailed crosstab, accessed 6 November 2026.','https://www.aphis.usda.gov/livestock-poultry-disease/avian/avian-influenza/hpai-detections/commercial-backyard-flocks'),('r2','USDA APHIS. Detections of Highly Pathogenic Avian Influenza in Wild Birds. Official CSV and surveillance notes, accessed 6 November 2026.','https://www.aphis.usda.gov/livestock-poultry-disease/avian/avian-influenza/hpai-detections/wild-birds'),('r3','Damodaran L, Jaeger AS, Moncla LH. Ecology and spread of the North American H5N1 epizootic. Nature 649, 432–441 (2026); online 12 November 2025. doi:10.1038/s41586-025-09737-x.','https://www.nature.com/articles/s41586-025-09737-x'),('r4','Ssematimba A et al. Estimating the time of Highly Pathogenic Avian Influenza virus introduction into United States poultry flocks during the 2022/24 epizootic. PLoS ONE 19(12):e0310733 (2024). doi:10.1371/journal.pone.0310733.','https://pmc.ncbi.nlm.nih.gov/articles/PMC11642945/'),('r5','Harrington WN et al. Rapid expansion of genotype D1.1 A(H5N1) influenza viruses in wild birds across North America during the 2024 migratory season. Nature Medicine 32, 1661–1665 (2026). doi:10.1038/s41591-026-04300-1.','https://www.nature.com/articles/s41591-026-04300-1'),('r6','Center for Epidemiology and Animal Health (2026). Status and Epidemiologic Analyses of HPAI-affected Poultry Flocks: September 30, 2025 Interim Report. USDA APHIS.','https://www.aphis.usda.gov/sites/default/files/hpai-epi-report-fy25-q4.pdf'),('r7','U.S. Census Bureau. 2024 cartographic boundary shapefiles, U.S. states, 1:20 million.','https://www2.census.gov/geo/tiger/GENZ2024/shp/cb_2024_us_state_20m.zip'),('r8','USDA NASS. Quick Stats and 2022 Census of Agriculture. Public inventory and operation-count data; investigated as follow-up denominators.','https://www.nass.usda.gov/Quick_Stats/'),('r9','NOAA NCEI. Climate Data Online. Public daily/monthly weather data; investigated as a follow-up explanatory source.','https://www.ncei.noaa.gov/cdo-web/')]
 content+='<h2>References</h2><ol>'+''.join(f'<li id="{i}"><a href="{u}">{html.escape(t)}</a></li>' for i,t,u in refs)+'</ol>'
 content+='<h2>Reproducibility</h2><p>See <a href="README.txt">README.txt</a>, <a href="investigation.ipynb">executed notebook</a>, <a href="scripts/analyze.py">analysis script</a> and machine-readable <a href="results/hypotheses.json">hypothesis results</a>. No external data are needed to rerun the frozen analysis after dependencies are installed. Explicit download scripts refresh snapshots and manifests; analysis never refreshes silently. This report was generated from executed result files. It is an exploratory scientific investigation for critical review, not a peer-reviewed estimate.</p>'
 document='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>U.S. bird flu: observational investigation</title><style>body{font:17px/1.65 Georgia,serif;color:#213039;max-width:1100px;margin:45px auto;padding:0 28px}h1,h2,h3,.subtitle{font-family:Arial,sans-serif;line-height:1.25}h1{font-size:38px}h2{margin-top:2em;border-bottom:1px solid #ccd7da;padding-bottom:8px}h3{margin-top:1.6em}.subtitle{color:#567078;font-size:15px}.takeaway{background:#e8f4f2;border-left:5px solid #159895;padding:20px}a{color:#126477}table{border-collapse:collapse;width:100%;font:14px/1.5 Arial,sans-serif;margin:24px 0}td,th{padding:10px;text-align:right;border-bottom:1px solid #d5dfe0}th{background:#f0f5f5}figure{margin:45px 0}img{max-width:100%;height:auto}figcaption{font:14px/1.5 Arial,sans-serif;color:#52656e}li{margin-bottom:10px}@media print{body{font-size:11pt;margin:0;max-width:none}figure,table{break-inside:avoid}h2,h3{break-after:avoid}a{color:inherit}}</style><body>'+content+'</body></html>'
 (ROOT/'REPORT.html').write_text(document)
 (ROOT/'sources/references.json').write_text(json.dumps([{'id':i,'title':t,'url':u,'consulted':'2026-11-06'} for i,t,u in refs],indent=2)+'\n')
 print('Wrote REPORT.html')
if __name__=='__main__':main()
